function equalGcdPairs(nums: number[]): number {
  const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));
  const go = (i: number, g1: number, g2: number): number => {
    if (i === nums.length) return g1 > 0 && g1 === g2 ? 1 : 0;
    const x = nums[i];
    return (go(i + 1, g1, g2) + go(i + 1, gcd(g1, x), g2) + go(i + 1, g1, gcd(g2, x))) % 1000000007;
  };
  return go(0, 0, 0);
}

