function equalGcdPairs(nums: number[]): number {
  const MOD = 1000000007, M = Math.max(...nums);
  const gcd = (a: number, b: number): number => { while (b) [a, b] = [b, a % b]; return a; };
  // g[x][a] = gcd(a, x), with gcd(0, x) = x
  const g: number[][] = [];
  for (let x = 0; x <= M; x++) { g.push([]); for (let a = 0; a <= M; a++) g[x].push(gcd(a, x)); }
  let dp = Array.from({ length: M + 1 }, () => new Array(M + 1).fill(0));
  dp[0][0] = 1;
  for (const x of nums) {
    const next = dp.map(row => row.slice());
    const gx = g[x];
    for (let a = 0; a <= M; a++) {
      const row = dp[a], na = next[gx[a]], nr = next[a];
      for (let b = 0; b <= M; b++) {
        const v = row[b];
        if (!v) continue;
        na[b] = (na[b] + v) % MOD;
        nr[gx[b]] = (nr[gx[b]] + v) % MOD;
      }
    }
    dp = next;
  }
  let total = 0;
  for (let k = 1; k <= M; k++) total = (total + dp[k][k]) % MOD;
  return total;
}

